script:
frappe.ui.form.on('Client', {
    refresh: function(frm) {
        if (!frm.is_new()) {
            frm.add_custom_button(__('Convert to Opportunity'), function() {
                // Open a new Opportunity Tracking doc with Client prefilled
                frappe.new_doc('Opportunity Tracking', {
                    client: frm.doc.name
                });

                // Update current Client status to "Opportunity"
                frm.set_value('status', 'Opportunity');
                frm.save();
            });
        }
    }
});
